(()=>{const q=s=>document.querySelector(s),set=(s,t)=>{const e=q(s);if(e&&t)e.textContent=t};async function run(){try{const r=await fetch('/api/podcas\
t/latest',{headers:{Accept:'application/json'}}),j=await r.json();if(!r.ok||!j.ok)return;set('[data-latest-episode-title]',j.title);set('[data-latest-\
episode-teaser]',j.teaser||j.description);document.querySelectorAll('[data-latest-episode-link]').forEach(a=>{a.href=j.episode_url||'/podcast/';a.removeAttribute('\
hidden')});const audio=q('[data-latest-audio]');if(audio&&j.audio_url){audio.src=j.audio_url;audio.removeAttribute('hidden')}const tr=q('[data-latest-\
transcript]');if(tr&&j.transcript_url){tr.href=j.transcript_url;tr.removeAttribute('hidden')}const box=q('[data-latest-video]');if(box&&j.youtube_video_id){
box.innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(j.youtube_video_id)}" title="${(j.title||'Latest Turing\'s Tor\
ch episode').replace(/["<>]/g,'')}" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; we\
b-share" allowfullscreen></iframe>`;box.removeAttribute('hidden')}}catch{}}document.readyState==='loading'?document.addEventListener('DOMContentLoaded\
',run,{once:true}):run()})();
